#include <iostream>
#include <string>
#include <vector>

using namespace std;

class TextDocumentAnalysis {
public:
    static string input(const string& s) {
        int length = s.length();
        bool inParentheses = false;
        int totalWords = 0;
        int maxWord = 0;
        int currentLength = 0;
        for (int i = 0; i < length; i++) {
            char c = s[i];
            if (c == '(') {
                if (currentLength > 0) {
                    if (currentLength > maxWord) maxWord = currentLength;
                    currentLength = 0;
                }
                inParentheses = true;
            } else if (c == ')') {
                if (currentLength > 0) {
                    totalWords++;
                    currentLength = 0;
                }
                inParentheses = false;
            } else if (c == '_') {
                if (currentLength > 0) {
                    if (inParentheses) {
                        totalWords++;
                    } else {
                        if (currentLength > maxWord) maxWord = currentLength;
                    }
                    currentLength = 0;
                }
            } else {
                currentLength++;
            }
        }
        if (currentLength > 0) {
            if (inParentheses) {
                totalWords++;
            } else {
                if (currentLength > maxWord) maxWord = currentLength;
            }
        }
        return to_string(maxWord) + " " + to_string(totalWords);
    }
};

int main() {
    string line;
    while (getline(cin, line)) {
        // Read and discard the first line
        if (!getline(cin, line)) break;
        cout << TextDocumentAnalysis::input(line) << endl;
    }
    return 0;
}

